sp_widget.client_script:
api.controller = function($window) {
    var c = this;

    c.guests = "2";
    c.roomType = "Any";

    c.searchRooms = function() {
        if (!c.checkin || !c.checkout) {
            return;
        }

        if (new Date(c.checkout) <= new Date(c.checkin)) {
            alert("Check-out must be later than check-in.");
            return;
        }

        $window.location.href = "?id=book_room";
    };
};

sp_widget.css:
.availability-section {
  background: #faf6ef;
  padding: 65px 7%;
  font-family: Arial, sans-serif;
  box-sizing: border-box;
}

.availability-heading {
  text-align: center;
  margin-bottom: 32px;
}

.availability-heading span {
  color: #9b7950;
  font-size: 10px;
  font-weight: bold;
  letter-spacing: 3px;
}

.availability-heading h2 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 36px;
  font-weight: normal;
  margin: 12px 0;
}

.availability-heading p {
  color: #6f756f;
  font-size: 14px;
  margin: 0;
}

.availability-form {
  max-width: 1250px;
  margin: 0 auto;
  padding: 25px;
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 6px;
  box-shadow: 0 8px 30px rgba(31, 58, 48, 0.07);
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr)) auto;
  align-items: end;
  gap: 20px;
}

.availability-field {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.availability-field label {
  color: #1f3a30;
  font-size: 10px;
  font-weight: bold;
  letter-spacing: 1.5px;
}

.availability-field input,
.availability-field select {
  width: 100%;
  box-sizing: border-box;
  height: 46px;
  padding: 0 10px;
  border: 1px solid #e7e1d4;
  border-radius: 3px;
  background: #ffffff;
  color: #2a2d29;
  font-size: 13px;
}

.availability-button {
  height: 46px;
  padding: 0 25px;
  border: none;
  border-radius: 3px;
  background: #1f3a30;
  color: #ffffff;
  font-size: 12px;
  font-weight: bold;
  cursor: pointer;
  white-space: nowrap;
}

.availability-button:hover {
  background: #162a22;
}

@media (max-width: 950px) {
  .availability-form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .availability-button {
    grid-column: span 2;
  }
}

@media (max-width: 550px) {
  .availability-form {
    grid-template-columns: 1fr;
  }

  .availability-button {
    grid-column: auto;
  }

  .availability-heading h2 {
    font-size: 29px;
  }
}
